// Transparent fit score from REAL enrichment fields only.
const p = items[0].json || {};
const title = (p.title || '').toLowerCase();
let seniority = 0;
if (/(founder|owner|ceo|cto|cfo|coo|chief|president|vp|head of|director)/.test(title)) seniority = 40;
else if (/(manager|lead|principal|staff)/.test(title)) seniority = 25;
else if (title) seniority = 10;
const idConf = typeof p.identity_confidence === 'number' ? p.identity_confidence : 0; // 0-100
const conf = typeof p.confidence === 'number' ? p.confidence : 0; // 0-1
const emailBonus = p.verified === true ? 15 : (p.email ? 5 : 0);
const fit_score = Math.max(0, Math.min(100, Math.round(seniority + idConf * 0.3 + conf * 100 * 0.15 + emailBonus)));
const hot = fit_score >= 60 && p.found === true;
return [{ json: { ...p, fit_score, hot } }];
